changeSet.sql:
-- This is a metadata-only migration, not a user project change.
-- Suppress the existing project audit and updated_at triggers so
-- deployment does not create false audit events attributed to each
-- project owner or alter the last genuine modification timestamp.
-- PostgreSQL DDL is transactional: a failed changeset restores the
-- enabled state when Liquibase rolls the transaction back.
ALTER TABLE bng.projects DISABLE TRIGGER write_audit_log;
ALTER TABLE bng.projects DISABLE TRIGGER set_updated_at;

UPDATE bng.projects
   SET last_modified_by = user_id
 WHERE last_modified_by IS NULL;

-- Database migrations are applied before a rolling application
-- deployment. Instances of the previous application version omit
-- last_modified_by on INSERT. Those instances can only write their
-- own projects, so user_id is the authenticated actor and is a safe
-- compatibility fallback until every instance runs the new code.
CREATE OR REPLACE FUNCTION bng.ensure_project_actor()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.last_modified_by IS NULL
       OR btrim(NEW.last_modified_by) = '' THEN
        NEW.last_modified_by := NEW.user_id;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER ensure_project_actor
    BEFORE INSERT ON bng.projects
    FOR EACH ROW
    EXECUTE FUNCTION bng.ensure_project_actor();

CREATE OR REPLACE FUNCTION bng.write_projects_audit_log()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO bng.audit_log (
        project_id,
        project,
        previous_project,
        user_id,
        bng_project_version,
        operation,
        audited_at
    ) VALUES (
        NEW.id,
        NEW.project,
        CASE WHEN TG_OP = 'UPDATE' THEN OLD.project ELSE NULL END,
        NEW.last_modified_by,
        NEW.bng_project_version,
        TG_OP,
        CURRENT_TIMESTAMP
    );
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

ALTER TABLE bng.projects ENABLE TRIGGER set_updated_at;
ALTER TABLE bng.projects ENABLE TRIGGER write_audit_log;

rollback.sql:
CREATE OR REPLACE FUNCTION bng.write_projects_audit_log()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO bng.audit_log (
        project_id,
        project,
        user_id,
        bng_project_version,
        operation,
        audited_at
    ) VALUES (
        NEW.id,
        NEW.project,
        NEW.user_id,
        NEW.bng_project_version,
        TG_OP,
        CURRENT_TIMESTAMP
    );
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS ensure_project_actor ON bng.projects;
DROP FUNCTION IF EXISTS bng.ensure_project_actor();

changeSet.sql:
CREATE OR REPLACE FUNCTION bng.reject_unaudited_project_delete()
RETURNS TRIGGER AS $$
BEGIN
    RAISE EXCEPTION
        'bng.projects deletion requires an audited deletion workflow'
        USING ERRCODE = 'insufficient_privilege';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER projects_reject_unaudited_delete
    BEFORE DELETE ON bng.projects
    FOR EACH ROW
    EXECUTE FUNCTION bng.reject_unaudited_project_delete();
